package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;

/** Host observations are fixtures here; publication study exercises actual Chromium controls. */
public class SmallBody161Test {
 static JSONObject scene(double side,double mass)throws Exception{
  var s=WorldFrames.copy(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0).getJSONObject("source"));
  var objects=s.getJSONArray("objects");while(objects.length()>2)objects.remove(objects.length()-1);
  s.put("title","Labelled161 small-body test");objects.getJSONObject(0).put("size",new JSONArray("[2,0.1,2]")).put("position",new JSONArray("[0,-0.05,0]"));
  objects.getJSONObject(1).put("size",new JSONArray(new double[]{side,side,side})).put("massKg",mass).put("position",new JSONArray(new double[]{0,side/2,0})).put("rotation",new JSONArray("[0,0,0,1]"));
  return SpatialScene.parse(s.toString(),UUID.randomUUID().toString());
 }
 static JSONObject action(double x,double z){return new JSONObject().put("targetXZ",new JSONArray(new double[]{x,z}));}
 static JSONObject request(JSONObject w,double x,double z){return new JSONObject().put("worldId",w.getString("id")).put("expectedRevision",w.getInt("revision")).put("expectedHash",w.getString("hash")).put("action",action(x,z));}
 static JSONObject waitFor(SmallStore161 f,String id)throws Exception{long until=System.nanoTime()+120_000_000_000L;while(System.nanoTime()<until){var j=f.read(id);if(!j.getString("status").equals("running"))return j;Thread.sleep(20);}throw new AssertionError("Native deadline");}
 static JSONObject observed(JSONObject j){var d=SmallReport161.data(j);var rows=d.getJSONArray("rows");var limits=SmallReport161.plot(d);var path=new JSONArray();for(Object raw:rows){var p=((JSONArray)raw).getJSONArray(2);path.put(new JSONArray(new double[]{(float)SmallReport161.point(p,limits)[0],(float)SmallReport161.point(p,limits)[1]}));}var states=new JSONArray();for(int i:new int[]{0,rows.length()/2,rows.length()-1})states.put(new JSONObject().put("index",i).put("label",SmallReport161.sampleText(rows.getJSONArray(i))).put("visible",true).put("pose",rows.getJSONArray(i).toString()).put("x",path.getJSONArray(i).get(0)).put("y",path.getJSONArray(i).get(1)));return new JSONObject().put("axes",SmallReport161.axes(limits)).put("summary",SmallReport161.summary(d)).put("scope",d.getString("scope")).put("source","Frozen starting state "+d.getString("sourceHash")+" · job "+d.getString("job")).put("path",path).put("states",states);}
 @Test(timeout=120000) public void realSmallBodyUsesBoundedWrenchesAndSettlesOnFloor()throws Exception{
  var s=SmallBody161.authored(scene(.05,.04));var p=SmallBody161.plan(s,action(.1,.06));var run=SmallBody161.execute(s,p,Files.createTempDirectory("native161"),()->{});
  assertTrue(run.toString(),run.getJSONObject("verification").getBoolean("passed"));assertEquals("completed",run.getString("status"));System.out.println("small161 "+run.getJSONObject("verification"));assertTrue(SmallBody161.margin(SmallBody161.body(s))<=.001);assertNotEquals(WorldFrames.hash(s),WorldFrames.hash(SmallBody161.after(s,run)));
 }
 @Test public void refusesForceUnknownAuthorityAndOversizedDomain()throws Exception{
  var s=SmallBody161.authored(scene(.05,.04));for(var in:List.of(action(.1,0).put("forceLimitN",.05),action(.6,0),action(.1,0).put("hardware",true),action(.1,0).put("coordinateRadiusM",.04)))assertThrows(IllegalArgumentException.class,()->SmallBody161.plan(s,in));
  assertThrows(IllegalArgumentException.class,()->SmallBody161.authored(scene(.2,.2)));
 }
 @Test(timeout=120000) public void heavierReverseMoveAndTraceCorruption()throws Exception{var s=SmallBody161.authored(scene(.15,.2));var run=SmallBody161.execute(s,SmallBody161.plan(s,action(-.2,-.1)),Files.createTempDirectory("native161-heavy"),()->{});assertTrue(run.getJSONObject("verification").toString(),run.getJSONObject("verification").getBoolean("passed"));var corrupt=WorldFrames.copy(run);corrupt.getJSONObject("initialState").getJSONArray("bodies").getJSONObject(0).getJSONArray("position").put(0,.5);assertThrows(Exception.class,()->SmallVerify161.verify(corrupt));}
 @Test(timeout=180000) public void reportRestartChainAndCorruptionRetainIndependentChecks()throws Exception{Path root=Files.createTempDirectory("durable161");String id,wid;try(var a=new WorkspaceStore(root);var f=new SmallStore161(root,a)){var w=f.create(scene(.06,.05));wid=w.getString("id");id=f.start(request(w,.08,.02)).getString("id");var j=waitFor(f,id);assertEquals(j.optString("reason"),"awaiting-report",j.getString("status"));assertEquals(0,f.world(wid).getInt("revision"));var o=observed(j);var bad=WorldFrames.copy(o).put("summary","all good");assertThrows(Exception.class,()->f.acknowledge(new JSONObject().put("id",id).put("observed",bad)));assertEquals(0,f.world(wid).getInt("revision"));f.acknowledge(new JSONObject().put("id",id).put("observed",o));assertTrue(f.verify(id).getBoolean("passed"));assertThrows(Exception.class,()->f.start(request(w,-.1,0)));}
 try(var a=new WorkspaceStore(root);var f=new SmallStore161(root,a)){assertTrue(f.verify(id).getBoolean("passed"));var w=f.world(wid);assertEquals(1,w.getInt("revision"));String second=f.start(request(w,-.07,-.04)).getString("id");var j=waitFor(f,second);assertEquals(j.optString("reason"),"awaiting-report",j.getString("status"));f.acknowledge(new JSONObject().put("id",second).put("observed",observed(j)));assertEquals(2,f.verify(second).getInt("worldRevision"));var saved=f.find("worlds",wid);SmallBody161.body(saved.getJSONObject("head")).getJSONArray("position").put(0,.3);saved.put("hash",WorldFrames.hash(saved.getJSONObject("head")));assertThrows(Exception.class,()->f.preview(request(saved,0,0)));}
 }
 @Test(timeout=120000) public void stopThenResumeRepeatsProvisionalStateAndCancelCannotCommit()throws Exception{var root=Files.createTempDirectory("stop161");try(var a=new WorkspaceStore(root);var f=new SmallStore161(root,a)){var w=f.create(scene(.05,.04));String id; synchronized(f){id=f.start(request(w,.1,0)).getString("id");f.control(id,"stop");}assertEquals(0,f.world(w.getString("id")).getInt("revision"));assertThrows(Exception.class,()->f.control(id,"other"));f.control(id,"resume");var j=waitFor(f,id);assertEquals(j.optString("reason"),"awaiting-report",j.getString("status"));assertEquals(1,j.getInt("resumes"));f.control(id,"cancel");assertThrows(Exception.class,()->f.acknowledge(new JSONObject().put("id",id).put("observed",observed(j))));assertEquals(0,f.world(w.getString("id")).getInt("revision"));}}
 @Test public void alteredPlanAndFractionalRevisionAreRefused()throws Exception{var root=Files.createTempDirectory("plan161");try(var a=new WorkspaceStore(root);var f=new SmallStore161(root,a)){var w=f.create(scene(.05,.04));assertThrows(Exception.class,()->f.preview(request(w,.1,0).put("expectedRevision",.5)));var p=f.preview(request(w,.1,0));p.put("liftHeightM",.1);assertThrows(Exception.class,()->SmallBody161.verifyPlan(w.getJSONObject("head"),p));}}

 @Test public void obstacleAndExpandedAllowanceCanRefuseBeforeMotion()throws Exception{var imported=scene(.05,.04);var raw=new JSONObject(imported.getString("sourceText"));var obstacle=WorldFrames.copy(raw.getJSONArray("objects").getJSONObject(1)).put("sourceId","obstacle").put("massKg",0).put("position",new JSONArray("[0.11,0.05,0]")).put("size",new JSONArray("[0.05,0.1,0.05]"));raw.getJSONArray("objects").put(obstacle);var s=SmallBody161.authored(SpatialScene.parse(raw.toString(),UUID.randomUUID().toString()));assertThrows(IllegalArgumentException.class,()->SmallBody161.plan(s,action(.11,0)));assertTrue(SmallBody161.plan(s,action(-.1,0)).getBoolean("passed"));}
 @Test(timeout=120000) public void fullReportPathAndReplaySamplesCannotBeChanged()throws Exception{var s=SmallBody161.authored(scene(.05,.04));var j=new JSONObject().put("id",UUID.randomUUID().toString()).put("before",s).put("plan",SmallBody161.plan(s,action(.1,.06)));j.put("run",SmallBody161.execute(s,j.getJSONObject("plan"),Files.createTempDirectory("report161"),()->{}));var o=observed(j);assertTrue(SmallReport161.audit(j,o).getBoolean("passed"));var changed=WorldFrames.copy(o);changed.getJSONArray("path").getJSONArray(7).put(0,0);assertThrows(Exception.class,()->SmallReport161.audit(j,changed));var hidden=WorldFrames.copy(o);hidden.getJSONArray("states").getJSONObject(1).put("visible",false);assertThrows(Exception.class,()->SmallReport161.audit(j,hidden));}

 @Test public void corruptSavedChecksumAndFailedWriteCannotAdvanceState()throws Exception{Path root=Files.createTempDirectory("checksum161");try(var a=new WorkspaceStore(root);var f=new SmallStore161(root,a)){f.create(scene(.05,.04));var old=f.state.toString();Files.createDirectory(f.root.resolveSibling("state.pending"));assertThrows(Exception.class,()->f.create(scene(.06,.04)));assertTrue(new JSONObject(old).similar(f.state));Files.delete(f.root.resolveSibling("state.pending"));}Path p=root.resolve("small-body161/state.json");var e=new JSONObject(Files.readString(p)).put("sha256","0".repeat(64));Files.writeString(p,e.toString());try(var a=new WorkspaceStore(root)){assertThrows(Exception.class,()->new SmallStore161(root,a));}}

}
